code_example:
#include <iostream>
#include <array>
template <typename T, size_t N>
class StaticArray {
public:
  T data[N];
  size_t size() const { return N; }
  T& operator[](size_t i) { return data[i]; }
  const T& operator[](size_t i) const { return data[i]; }
};

template <typename T, size_t N>
void printArray(const StaticArray<T,N>& arr) {
  for (size_t i = 0; i < N; ++i) {
    std::cout << arr[i] << " ";
  }
  std::cout << std::endl;
}

int main() {
  StaticArray<int, 5> intArray = {{1, 2, 3, 4, 5}};
  StaticArray<double, 3> doubleArray = {{1.1, 2.2, 3.3}};
  printArray(intArray);
  printArray(doubleArray);
  return 0;
}
